def re_arrange_array(arr):
    # Partition the array so that all negative elements come before positive ones
    # This can be done in-place using two pointers
    i, j = 0, 0
    while j < len(arr):
        if arr[j] < 0:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
        j += 1
    return arr

def second_smallest(lst):
    unique_numbers = sorted(set(lst))
    if len(unique_numbers) < 2:
        raise ValueError("List must contain at least two distinct numbers")
    return unique_numbers[1]

import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r'\s+', ' ', s)

def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return False  # A single character or empty string cannot alternate between two characters

    # Extract the two characters expected to alternate
    char1 = s[0]
    char2 = None

    for c in s[1:]:
        if c != char1:
            char2 = c
            break

    if char2 is None:
        return False  # Only one unique character present

    # Check if the string contains only these two characters and they alternate
    for i in range(len(s)):
        expected_char = char1 if i % 2 == 0 else char2
        if s[i] != expected_char:
            return False

    return True

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_length_words)

